entries[124334] = { ["name"] = "Schnelle Reflexe", ["text"] = "Erhöht Eure Chance zu parieren um 5%.\n\nImmer wenn Ihr einen Angriff pariert, schlagt Ihr reflexartig zurück und fügt dem Gegner [4.5 * (( 1 * 1 ) * ( 0.898882 * (Haupthand-Min-DPS * 1 + 1 * (Haupthand-Min-DPS / 2) ) + (Angriffskraft / 14) - 1))] bis [4.5 * (( 1 * 1 ) * ( 0.898882 * (Haupthand-Max-DPS * 1 + 1 * (Haupthand-Max-DPS / 2) ) + (Angriffskraft / 14) + 1))] Schaden zu. Dieser Effekt unterliegt einer Abklingzeit von 1 Sek.\n(1s Abklingzeit)" }
entries[124335] = { ["name"] = "Schnelle Reflexe", ["text"] = "Nahkampfreichweite\nSofort\nImmer wenn Ihr einen Angriff pariert, schlagt Ihr reflexartig zurück und fügt dem Gegner [0.3 * (( 1 * 1 ) * ( 0.898882 * (Haupthand-Min-DPS * 1 + 1 * (Haupthand-Min-DPS / 2) ) + (Angriffskraft / 14) - 1))] bis [0.3 * (( 1 * 1 ) * ( 0.898882 * (Haupthand-Max-DPS * 1 + 1 * (Haupthand-Max-DPS / 2) ) + (Angriffskraft / 14) + 1))] Schaden zu. Dieser Angriff unterliegt einer Abklingzeit von 1 Sek." }
