entries[124442] = { ["name"] = "Glyphe 'Aspekt des Wildtiers'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Aspekt des Wildtiers'.\n\nDer Jäger nimmt die Aspekte eines Wildtiers an: Er kann nicht aufgespürt werden. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[124443] = { ["name"] = "Glyphe 'Schwarzes Eis'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Euch im Effektbereich Eurer Frostfalle aufhaltet, wird Euer Bewegungstempo um 50% erhöht." }
entries[124444] = { ["name"] = "Glyphe 'Feuerodem'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr 'Feuerodem' gegen Ziele einsetzt, die von 'Benebelnde Dämpfe' betroffen sind, werden sie 3 Sek. lang desorientiert." }
entries[124445] = { ["name"] = "Glyphe 'Furorfäuste'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr 'Furorfäuste' kanalisiert, ist Eure Parierchance um 100% erhöht." }
entries[124446] = { ["name"] = "Glyphe 'Aufprall'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Aufprall' um 10 Meter." }
entries[124447] = { ["name"] = "Glyphe 'Andauernde heilende Sphäre'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nKlassen: Mönch\n25\nBenutzen:" }
entries[124448] = { ["name"] = "Glyphe 'Schnelles Rollen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nFür 5 Sek., nachdem Ihr 'Rolle' oder 'Chitorpedo' eingesetzt habt, ist die Reichweite dieser Fähigkeiten um 30% erhöht." }
entries[124449] = { ["name"] = "Glyphe 'Schutz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Absorptionsmenge von 'Schutz' um 10%, dafür kann 'Schutz' nur magischen Schaden absorbieren." }
entries[124450] = { ["name"] = "Glyphe 'Manatee'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Manatee' ist nun ein Spontanzauber und zehrt zwei Aufladungen auf. Allerdings wird eine Abklingzeit von 10 Sek. ausgelöst." }
entries[124451] = { ["name"] = "Glyphe 'Zenmeditation'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt nun 'Zenmeditation' in der Bewegung kanalisieren." }
entries[124452] = { ["name"] = "Glyphe 'Erneuernder Nebel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Erneuernder Nebel' bewegt sich nun zum am weitesten entfernten verletzten Ziel innerhalb von 40 Metern statt zum nächsten verletzten Ziel innerhalb von 20 Metern." }
entries[124453] = { ["name"] = "Glyphe 'Wirbelnder Kranichtritt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr bewegt Euch mit Eurer normalen Geschwindigkeit, während Ihr 'Wirbelnder Kranichtritt' einsetzt." }
entries[124454] = { ["name"] = "Glyphe 'Wirbelnde Feuerblüte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wirbelnde Feuerblüte' benötigt ein gegnerisches Ziel anstatt sich vorwärts zu bewegen. Dafür werden Ziele nicht mehr bewegungsunfähig gemacht." }
entries[124455] = { ["name"] = "Glyphe 'Wallender Nebel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wallender Nebel' benötigt kein Ziel mehr und heilt stattdessen das am schwersten verletzte Ziel innerhalb von 40 Metern." }
entries[124456] = { ["name"] = "Glyphe 'Berührung des Todes'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Berührung des Todes' kostet kein Chi mehr, dafür wird aber die Abklingzeit um 2 Minuten erhöht." }
entries[124457] = { ["name"] = "Glyphe 'Transzendenz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Transzendenz: Transfer' um 5 Sek." }
entries[124458] = { ["name"] = "Heilende Sphäre", ["text"] = "Unbegrenzte Reichweite\nSofort\nIhr bildet am Zielort 1 Min. lang eine heilende Sphäre aus heilendem Nebel. Wenn Verbündete durch sie hindurchlaufen, verbrauchen sie die Sphäre und heilen sich selbst um [((Angriffskraft * 0.75) + 9986 )] Gesundheit.\n\nEs können pro Mönch maximal 3 heilende Sphären gleichzeitig aktiv sein.\n\nWenn die Dauer der heilenden Sphäre abläuft bevor sie genutzt wurde, wird ein Verbündeter innerhalb von 6 Metern um die Sphäre um 50% ihres Effekts geheilt." }
entries[124459] = { ["name"] = "Glyphe 'Gedankenschinden'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Gedankenschinden' verringert das Bewegungstempo des Ziels nicht mehr. Stattdessen wird jedes Mal, wenn 'Gedankenschinden' Schaden verursacht, Euer Bewegungstempo 5 Sek. lang um 15% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[124460] = { ["name"] = "Glyphe 'Vampirumarmung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Vampirumarmung' wandelt zusätzliche 50% Eures verursachten Schadens in Heilung um, die Gesamtdauer des Effekts wird jedoch um 5 Sek. verringert." }
entries[124461] = { ["name"] = "Glyphe 'Schattenwort: Tod'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schattenwort: Tod' kann jetzt jederzeit gewirkt werden, fügt Zielen mit über 20% Gesundheit jedoch nur 25% des Schadens zu [ Gedankenschinden : und erzeugt beim Einsatz gegen sie keine Schattenkugeln mehr ].\n\nDas Wirken von 'Schattenwort: Tod' fügt Euch nun Schaden in Höhe des Schadens zu, den der Zauber einem Gegner mit mehr als 20% Gesundheit zufügen würde." }
entries[124463] = { ["name"] = "Glyphe 'Glück im Unglück'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Eure Gesundheit unter 25% fällt, wird automatisch eine kostenlose heilende Sphäre neben Euch erzeugt. Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten. (30s Abklingzeit)" }
entries[124464] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "100 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das sofort 780 Schattenschaden sowie im Verlauf von 18 Sek. zusätzlich ( 4678 - 780 ) Schattenschaden verursacht." }
entries[124465] = { ["name"] = "Vampirberührung", ["text"] = "100 Meter Reichweite\nSofort\nFügt dem Ziel im Verlauf von 15 Sek. insgesamt 5 Schattenschaden zu. Jedes Mal, wenn der regelmäßige Effekt von 'Vampirberührung' Schaden verursacht, gewinnt Ihr 2% Eures maximalen Manas." }
entries[124466] = { ["name"] = "Glyphe 'Jindujun'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nZiele Eures Zaubers 'Levitieren' reiten nun während der Effektdauer auf einer Wolke." }
entries[124467] = { ["name"] = "Verschlingende Seuche", ["text"] = "100 Meter Reichweite\nSofort\nVerbraucht alle Schattenkugeln, um dem Ziel 0 Schattenschaden zuzufügen und es 6 Sek. lang alle 1.00 Sek. zusätzlich 0 Schattenschaden erleiden zu lassen. Heilt den Zaubernden außerdem um 1% seiner Maximalgesundheit, wenn der Zauber regelmäßigen Schaden verursacht.\n\nDas Ausmaß des Schadens und der Heilung hängen von der Anzahl der verbrauchten Schattenkugeln ab. [ Trost und Wahnsinn : Während 'Verschlingende Seuche' aktiv ist, wird der Schaden von 'Gedankenschinden' pro verbrauchter Schattenkugel um 33% erhöht ]" }
entries[124468] = { ["name"] = "Gedankenschinden", ["text"] = "100 Meter Reichweite\nSofort\nGreift die Gedanken des Ziels mit Schattenenergie an und fügt ihm so im Verlauf von 3 Sek. 3148 Schattenschaden zu. [ Glyphe 'Gedankenschinden' : Jedes Mal, wenn 'Gedankenschinden' Schaden verursacht, wird das Bewegungstempo des Priesters 5 Sek. lang um 15% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar / Zusätzlich wird sein Bewegungstempo um 50% verringert.]" }
entries[124469] = { ["name"] = "Gedankenexplosion", ["text"] = "100 Meter Reichweite\nSofort\nLöst eine Explosion von Schattenmagie um das Ziel aus, die allen Feinden im Umkreis von 10 Metern 5 Sek. lang alle 1 Sek. 315 Schattenschaden zufügt." }
